// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;

    function setUp() public { c = new MyContract(); }

    function testFuzz_property(uint256 amount, bool useReverting) public {
        vm.assume(amount > 0 && amount <= 1 ether);

        address receiverAddr;
        if (useReverting) {
            Reverter r = new Reverter();
            receiverAddr = address(r);
        } else {
            Receiver r = new Receiver();
            receiverAddr = address(r);
        }

        vm.deal(address(c), 1 ether);

        bool ok;
        try c.sendTo(receiverAddr, amount) {
            ok = true;
        } catch {
            ok = false;
        }

        if (useReverting) {
            assertTrue(!ok);
        } else {
            assertTrue(ok);
        }
    }
}

contract Reverter {
    fallback() external payable { revert("nope"); }
    receive() external payable { revert("nope"); }
}

contract Receiver {
    receive() external payable {}
}
